// DatasetCard (UI-SPEC « /datasets », D-40, LIC-01; phase 04.5 plan 11, B7): one compact row per
// entry of `GET /v1/datasets` — name, producer and state, anchored on the catalogue key, with the link
// that chooses it — and, when chosen, the one rendering of its metadata (DatasetDetail) in a native
// `details` opened. The fixture is generated by the backend (`list_dataset_infos`) and pinned to the
// catalogue by `test_datasets_reutilisation.py`. Every fact below is read in the chosen card, so the
// row and the detail together keep what the card of the starting SHA rendered (inventory:
// DatasetDetail.test.ts).
import { render, within } from '@testing-library/svelte';
import { afterEach, describe, expect, it, vi } from 'vitest';
import DatasetCard from './DatasetCard.svelte';
import type { DatasetPublic } from '$lib/api/datasets';
import fixture from '$lib/data/__fixtures__/datasets-api.json';

const JEUX = fixture.donnees as DatasetPublic[];
const jeu = (nom: string) => structuredClone(JEUX.find((item) => item.nom === nom)!);
const INSTANCE = ['44', '85'];

function rendre(jeuServi: DatasetPublic, choisi: boolean, departementsInstance = INSTANCE) {
	return render(DatasetCard, {
		props: { jeu: jeuServi, departementsInstance, href: `/datasets?q=x&jeu=${jeuServi.nom}#${jeuServi.nom}`, choisi }
	});
}

/** The chosen card: its row and its detail. */
function carte(jeuServi: DatasetPublic, departementsInstance = INSTANCE): HTMLElement {
	return rendre(jeuServi, true, departementsInstance).container;
}

const detail = (racine: HTMLElement) => racine.querySelector<HTMLElement>('.dataset-detail')!;

const GENERIC_FREE_REUSE = 'réutilisation libre avec mention de la source';

afterEach(() => vi.restoreAllMocks());

describe('DatasetCard — the compact row', () => {
	it('is anchored on the catalogue key, names the dataset by the link that chooses it, its producer and its state', () => {
		const dvf = jeu('dvf');
		const { container } = rendre(dvf, false);
		const article = container.querySelector('article')!;
		expect(article.id).toBe('dvf');
		const ligne = within(article);
		const lien = ligne.getByRole('link', { name: dvf.provenance!.nom });
		expect(lien.getAttribute('href')).toBe('/datasets?q=x&jeu=dvf#dvf');
		expect(lien).not.toHaveAttribute('aria-current');
		// 04.8-06: the row ends with the accent arrow, hidden from assistive technologies; the accessible name
		// of the heading is still the name of the source, exactly.
		const titre = ligne.getByRole('heading', { level: 3 });
		expect(ligne.getByRole('heading', { level: 3, name: dvf.provenance!.nom })).toBe(titre);
		expect(titre.querySelector('.dataset-ligne-nom')?.textContent).toBe(dvf.provenance!.nom);
		expect(titre.querySelector('.fleche')?.getAttribute('aria-hidden')).toBe('true');
		expect(article.textContent).toContain(dvf.provenance!.producteur);
		// Review of 2026-11-11: the state of a dataset that is read is plain text, with the date of its last
		// import; no badge.
		expect(article.querySelector('.dataset-etat')?.textContent).toBe('Importé le 22 sept. 2026');
		expect(article.querySelector('.dataset-etat-mot')?.textContent).toBe('Importé');
		expect(article.querySelector('.dataset-badge')).toBeNull();
	});

	it('words an imported dataset without a date when the API serves none, never an invented one', () => {
		const dvf = jeu('dvf');
		dvf.provenance!.derniere_importation_reussie = null;
		const { container } = rendre(dvf, false);
		expect(container.querySelector('article .dataset-etat')?.textContent).toBe('Importé');
	});

	it('keeps a badge for a dataset not imported yet: an exception the reader must notice', () => {
		const { container } = rendre(jeu('batiments'), false);
		expect(container.querySelector('article .dataset-badge')?.textContent).toBe('Pas encore importé');
		expect(container.querySelector('article .dataset-etat')).toBeNull();
	});

	it('is a heading of level 4 under a group title, its detail blocks one level under', () => {
		const dvf = jeu('dvf');
		const { container } = render(DatasetCard, {
			props: { jeu: dvf, departementsInstance: INSTANCE, href: '/datasets?jeu=dvf#dvf', choisi: true, niveau: 4 }
		});
		expect(container.querySelector('article h4')?.textContent).toBe(`${dvf.provenance!.nom}→`);
		expect(container.querySelector('article h3')).toBeNull();
		expect([...container.querySelectorAll('.dataset-detail h5')].map((titre) => titre.textContent)).toEqual([
			'Limites de la source',
			'Conditions de réutilisation',
			'Restrictions de réutilisation'
		]);
		expect(container.querySelector('.dataset-detail h4')).toBeNull();
	});

	it('mounts no metadata when it is not chosen', () => {
		const { container } = rendre(jeu('dvf'), false);
		expect(container.querySelector('.dataset-detail')).toBeNull();
		expect(container.querySelector('details')).toBeNull();
		expect(container.textContent).not.toContain('Licence');
	});

	// Review of 09/11: the row already opens the source, a second fold « Détail de la source » repeated it.
	it('chosen: the link is current and the detail follows the row directly, with no second fold', () => {
		const { container } = rendre(jeu('dvf'), true);
		const article = container.querySelector('article')!;
		expect(within(article).getByRole('link')).toHaveAttribute('aria-current', 'true');
		expect(container.querySelector('details')).toBeNull();
		expect(container.querySelector('summary')).toBeNull();
		expect(container.textContent).not.toContain('Détail de la source');
		const ouvert = article.nextElementSibling!;
		expect(ouvert.classList.contains('dataset-ouvert')).toBe(true);
		expect(ouvert.querySelectorAll('.dataset-detail')).toHaveLength(1);
		expect(within(ouvert as HTMLElement).getByText('Licence')).toBeTruthy();
	});

	it('chosen: the detail does not repeat the name, producer and plain badge its row already shows', () => {
		const { container } = rendre(jeu('dvf'), true);
		const corps = detail(container);
		expect(corps.querySelector('h3')).toBeNull();
		expect(corps.querySelector('.dataset-producer')).toBeNull();
		expect(corps.querySelector('.dataset-badge')).toBeNull();
		expect(corps.getAttribute('aria-labelledby')).toBe(container.querySelector('article h3')!.id);
	});

	it('gives a quarantined dataset the « Non qualifié » badge in its row, never « Importé »', () => {
		const { container } = rendre(jeu('encadrement_loyers'), false);
		expect(container.querySelector('.dataset-badge-warn')?.textContent).toBe('Non qualifié');
		expect(container.textContent).not.toContain('Importé');
	});

	it('refuses a status it cannot word, names it once on the console and shows « Non servi »', () => {
		const error = vi.spyOn(console, 'error').mockImplementation(() => {});
		const racine = carte({ ...jeu('dvf'), statut: 'available' });
		expect(racine.querySelector('article')!.textContent).toContain('Non servi');
		// The row says it; the detail under it does not repeat it (review of 09/11).
		expect(detail(racine).textContent).not.toContain('Non servi');
		expect(racine.textContent).not.toContain('available');
		expect(error).toHaveBeenCalledTimes(1);
		expect(error).toHaveBeenCalledWith(expect.stringContaining('dvf (available)'));
	});
});

describe('DatasetCard — identity and served facts of the chosen card', () => {
	// Replaces « keeps meaning-changing facts visible while secondary facts stay in native HTML
	// details » (starting SHA): the detail of a chosen source shows every fact, none folded.
	it('shows every fact of the chosen source, none folded behind another details', () => {
		const dvf = jeu('dvf');
		const corps = detail(carte(dvf));
		expect(corps.querySelector('details')).toBeNull();
		// Review of 2026-11-11: what the source does not cover is read before the terms of its reuse.
		expect([...corps.querySelectorAll('.dataset-block-title')].map((titre) => titre.textContent)).toEqual([
			'Limites de la source',
			'Conditions de réutilisation',
			'Restrictions de réutilisation'
		]);
		expect([...corps.querySelectorAll('dt')].map((dt) => dt.textContent)).toEqual([
			'Licence',
			'Source',
			'Période amont',
			'Dernière importation réussie',
			'Cadence',
			'Couverture'
		]);
		expect(corps.textContent).toContain(dvf.reutilisation!.licence);
		expect(corps.textContent).toContain(dvf.provenance!.periode.label!);
		expect(corps.textContent).toContain('22 septembre 2026');
	});

	it('names the dataset and its producer in its row, its licence link in the detail', () => {
		const dvf = jeu('dvf');
		const racine = carte(dvf);
		const ligne = within(racine.querySelector('article')!);
		expect(ligne.getByRole('heading', { level: 3 }).textContent).toBe(`${dvf.provenance!.nom}→`);
		expect(ligne.getByText(dvf.provenance!.producteur)).toBeTruthy();
		const corps = within(detail(racine));
		const licence = corps.getByRole('link', { name: dvf.reutilisation!.licence });
		expect(licence.getAttribute('href')).toBe(dvf.reutilisation!.licence_url);
		expect(detail(carte(dvf)).textContent).toContain('vérifiée le 21 septembre 2026');
		expect(corps.getByRole('link', { name: 'Page du producteur' }).getAttribute('href')).toBe(dvf.provenance!.url);
	});

	it('gives the period, the cadence and the last successful import as served', () => {
		const dpe = jeu('dpe');
		const text = detail(carte(dpe)).textContent ?? '';
		expect(text).toContain(dpe.provenance!.periode.label!);
		expect(text).toContain(`${dpe.provenance!.cadence.label}, selon le producteur`);
		expect(text).toContain('22 septembre 2026');
		const monuments = detail(carte(jeu('monuments'))).textContent ?? '';
		expect(monuments).toContain('Non déclarée');
		expect(monuments).toContain('Non renseignée dans le catalogue');
		expect(monuments).not.toContain('irrégulière');
	});

	it('words a proxied dataset and a hosted dataset not imported yet', () => {
		const racine = carte(jeu('georisques'));
		const proxy = racine.textContent ?? '';
		// Lot 8 of 4.9, reworded on 2026-11-11: the row says « Lu en direct », the detail keeps the whole
		// wording (level 2).
		expect(racine.querySelector('article .dataset-etat')?.textContent).toBe('Lu en direct');
		expect(racine.querySelector('article .dataset-badge')).toBeNull();
		expect(detail(racine).querySelector('.dataset-state')?.textContent?.trim()).toBe('Lu en direct chez le producteur, sans import');
		expect(racine.querySelector('article')?.textContent).not.toContain('sans import');
		expect(proxy).toContain('Sans objet : lu en direct');
		expect(proxy).toContain('Glissante');
		const batiments = carte(jeu('batiments')).textContent ?? '';
		expect(batiments).toContain('Pas encore importé');
		expect(batiments).toContain('Aucune');
	});

	it('says which hosted departements a dataset serves, never a hard-coded territory', () => {
		expect(carte(jeu('dvf')).textContent).toContain('Tous les départements hébergés');
		const partiel = jeu('loyers');
		partiel.hebergement = { etat: 'heberge', motif: null, departements: ['2A'] };
		expect(carte(partiel, ['2A', '976']).textContent).toContain('Tous les départements hébergés sauf Mayotte (976)');
		// Every code the backend serves is named, Saint-Pierre-et-Miquelon included.
		expect(carte(partiel, ['2A', '975']).textContent).toContain(
			'Tous les départements hébergés sauf Saint-Pierre-et-Miquelon (975)'
		);
	});
});

describe('DatasetCard — quarantine, coverage and unknown states', () => {
	it('gives a quarantined dataset the « Non qualifié » badge and its served reason', () => {
		for (const nom of ['permis', 'encadrement_loyers']) {
			const servi = jeu(nom);
			const text = carte(servi).textContent ?? '';
			expect(text).toContain('Non qualifié');
			expect(text).toContain('Ce jeu est en quarantaine : ses valeurs ne sont pas présentées comme fiables.');
			expect(text).toContain(servi.quarantaine!);
			// Never presented as available.
			expect(text).not.toContain('Importé');
		}
	});

	it('keeps the served coverage of a quarantined hosted dataset (encadrement_loyers)', () => {
		const racine = carte(jeu('encadrement_loyers'));
		const couverture = [...racine.querySelectorAll('dt')].find((dt) => dt.textContent === 'Couverture');
		expect(couverture?.nextElementSibling?.textContent?.trim()).toBe('Tous les départements hébergés');
		expect(racine.textContent).not.toContain('Non servi');
	});

	it('keeps the hosting reason of a quarantined dataset out of coverage (permis)', () => {
		const text = carte(jeu('permis')).textContent ?? '';
		expect(text).toContain('Hors couverture · non couvert par la source');
		expect(text).toContain('La source ne couvre pas ce territoire.');
	});

	it('gives a dataset out of coverage the badge and the sentence of its served reason', () => {
		const racine = carte(jeu('antennes'));
		expect(racine.querySelector('article .dataset-badge-warn')?.textContent).toBe('Hors couverture · jeu non installé');
		// A warning badge is an honesty fact: the detail carries it too (integration of 09/11).
		expect(detail(racine).querySelector('.dataset-badge-warn')?.textContent).toBe('Hors couverture · jeu non installé');
		expect(racine.textContent).toContain('Ce site ne propose pas ce jeu de données.');
	});
});

describe('DatasetCard — reuse restrictions apart from the limits of the source (LIC-01, LIC-02)', () => {
	it('renders the DVF restrictions in their own block, apart from the limits', () => {
		const dvf = jeu('dvf');
		const corps = within(carte(dvf));
		const restrictions = corps.getByRole('region', { name: 'Restrictions de réutilisation' });
		const limites = corps.getByRole('region', { name: 'Limites de la source' });
		expect(within(restrictions).getAllByRole('listitem').map((li) => li.textContent)).toEqual(dvf.reutilisation!.restrictions);
		expect(limites.textContent).toContain(dvf.limites_source!.chapeau);
		expect(within(limites).getAllByRole('listitem').map((li) => li.textContent)).toEqual(dvf.limites_source!.puces);
		for (const restriction of dvf.reutilisation!.restrictions) {
			expect(limites.textContent).not.toContain(restriction);
		}
		expect(restrictions.textContent).toContain('réidentification');
		expect(restrictions.textContent).toContain('indexation');
	});

	it('shows no restriction block when the producer states none, and keeps its reuse conditions', () => {
		const ban = jeu('ban');
		const corps = within(carte(ban));
		expect(corps.queryByRole('region', { name: 'Restrictions de réutilisation' })).toBeNull();
		expect(corps.queryByRole('region', { name: 'Limites de la source' })).toBeNull();
		expect(corps.getByRole('region', { name: 'Conditions de réutilisation' }).textContent).toContain(ban.reutilisation!.conditions);
	});

	it('states the share-alike condition of every ODbL dataset, never the generic sentence', () => {
		const odbl = JEUX.filter((item) => item.reutilisation?.licence.includes('ODbL'));
		expect(odbl.map((item) => item.nom).sort()).toEqual(['encadrement_loyers', 'gares']);
		for (const item of odbl) {
			expect(carte(structuredClone(item)).textContent ?? '').toContain("partage à l'identique");
		}
		for (const item of JEUX) {
			expect(carte(structuredClone(item)).textContent).not.toContain(GENERIC_FREE_REUSE);
		}
	});
});
